  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Source Serif 4";
  font-weight: 400;
  src: url("fonts/source-serif-4-latin-400-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #26302f;
  background: #f7f8f6;
}

a {
  color: inherit;
}

/* Header and main share one capped width, so the content does not spread to the edges of a wide screen. */
.site-header,
main {
  max-width: 1120px;
  margin: 0 auto;
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px 24px;
  padding: 24px 48px;
}

.logo {
  font-family: "Source Serif 4", serif;
  font-size: 24px;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 28px;
}

.site-nav a {
  text-decoration: none;
  font-size: 16px;
  white-space: nowrap;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 64px;
  padding: 48px 48px 64px;
}

.hero-text {
  flex: 1 1 auto;
  max-width: 600px;
}

h1 {
  margin: 0 0 20px;
  font-family: "Source Serif 4", serif;
  font-size: 44px;
  font-weight: 400;
  line-height: 1.15;
  color: #1b2423;
  text-wrap: balance;
}

.lead {
  margin: 0 0 20px;
  font-size: 18px;
  line-height: 1.6;
